#!/usr/bin/env node
/*
 * Bookam mobile app - polish update (consolidated, safe to run once).
 * Run from the project root:   node apply-bookam-polish.js
 *
 * Changes:
 *   - Search + Refine Search: every coloured emoji icon replaced with
 *     clean black-and-white line icons (amenities, rating stars,
 *     verified badge, empty states, image fallbacks).
 *   - Home + booking detail screens: same monochrome badge / star /
 *     fallback treatment, so the whole app reads as one icon set.
 *   - Home: em dash removed from the empty-state text.
 *   - Bottom tabs: smooth shift animation + a light haptic on tab press.
 *
 * This includes the earlier UI update too, so it is the only script you
 * need to run. After it runs:
 *   git add -A && git commit -m "ui polish: monochrome icons, tab motion" && git push
 * Then press r in the Expo terminal to reload.
 */
const fs = require('fs');
const path = require('path');

const FILES = {
  "app/tabs/home.tsx": "",
  "app/tabs/explore.tsx": "",
  "app/tabs/_layout.tsx": "",
  "app/search/filter.tsx": "",
  "app/booking/detail-active.tsx": "",
  "app/booking/detail-review.tsx": ""
};

for (const [rel, data] of Object.entries(FILES)) {
  const full = path.join(__dirname, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(data, 'base64'));
  console.log('  wrote  ' + rel);
}
console.log('\nDone. Next:');
console.log('  git add -A && git commit -m "ui polish: monochrome icons, tab motion" && git push');
console.log('  Press r in the Expo terminal to reload and see it.');
